const body = $input.first().json.body;

const tiers = {
  'conteudo-gratuito':    { tier: 1, tier_label: 'Tráfego / Isca', emoji: '📥', destaque: '' },
  'ebook-codigos':        { tier: 2, tier_label: 'Entrada',        emoji: '📖', destaque: '' },
  'comunidade':           { tier: 3, tier_label: 'Comunidade',     emoji: '👥', destaque: '' },
  'curso-online':         { tier: 4, tier_label: 'Curso Online',   emoji: '🎓', destaque: 'Boa venda!' },
  'acompanhamento-grupo': { tier: 5, tier_label: 'High Ticket',   emoji: '🚀', destaque: 'HIGH TICKET FECHADO!' },
  'mentoria-individual':  { tier: 6, tier_label: 'Ultra High',    emoji: '💎', destaque: 'ULTRA HIGH FECHADO!' },
};

const info = tiers[body.produto_slug] || { tier: 0, tier_label: 'Desconhecido', emoji: '❓', destaque: '' };

const valor_fmt = new Intl.NumberFormat('pt-BR', {
  style: 'currency',
  currency: 'BRL'
}).format(body.valor || 0);

const aprovado_dt = new Date(body.aprovado_em);
const data_fmt = aprovado_dt.toLocaleString('pt-BR', {
  timeZone: 'America/Sao_Paulo',
  day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit'
});

const forma_icon = {
  pix:      '🔷 PIX',
  cartao:   '💳 Cartão',
  gratuito: '🎁 Gratuito',
  boleto:   '📄 Boleto',
};
const forma_fmt = forma_icon[body.forma_pagamento] || body.forma_pagamento;

const header = info.destaque
  ? `${info.emoji} *${info.destaque} — Método C.A*`
  : `🔔 *Nova venda — Método C.A*`;

return [{ json: { ...body, ...info, valor_fmt, data_fmt, forma_fmt, header } }];
